import{_ as p,a0 as r,w as l,s as d,I as o,x as n,a1 as i,A as s,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Antergos Linux 中使用 iPhone | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Antergos Linux 中使用 iPhone | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Antergos Linux 中使用 iPhone | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Antergos Linux 中使用 iPhone | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 How To Use iPhone In Antergos Linux","title":"如何在 Antergos Linux 中使用 iPhone","tag":"201511","desc":""},"relativePath":"201511/20151012 How To Use iPhone In Antergos Linux.md","filePath":"[post].md"}'),u={name:"201511/20151012 How To Use iPhone In Antergos Linux.md"};function a(g,e,P,m,x,f){const t=r("Link");return l(),d("div",null,[e[20]||(e[20]=o("h1",{id:"如何在-antergos-linux-中使用-iphone",tabindex:"-1"},[n("如何在 Antergos Linux 中使用 iPhone "),o("a",{class:"header-anchor",href:"#如何在-antergos-linux-中使用-iphone","aria-label":"Permalink to “如何在 Antergos Linux 中使用 iPhone”"},"​")],-1)),e[21]||(e[21]=o("p",null,[o("img",{src:"http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-Antergos-Arch-Linux.jpg",alt:""})],-1)),e[22]||(e[22]=o("p",null,"在Arch Linux中使用iPhone遇到麻煩了麼？iPhone和Linux從來都沒有很好地集成。本教程中，我會向你展示如何在Antergos Linux中使用iPhone，對於同樣基於Arch的的Linux發行版如Manjaro也應該同樣管用。",-1)),o("p",null,[e[2]||(e[2]=n("我最近購買了一台全新的iPhone 6S，當我連接到Antergos Linux中要拷貝一些照片時，它完全沒有檢測到它。我看見iPhone正在被充電並且我已經允許了iPhone“信任這台電腦”，但是還是完全沒有檢測到。我嘗試運行",-1)),e[3]||(e[3]=o("code",null,"dmseg",-1)),e[4]||(e[4]=n("但是沒有關於iPhone或者Apple的信息。有趣的是我當我安裝好了",-1)),i(t,{href:"http://www.libimobiledevice.org/"},{default:s(()=>[...e[0]||(e[0]=[n("libimobiledevice",-1)])]),_:1}),e[5]||(e[5]=n("，這個就可以解決",-1)),i(t,{href:"http://itsfoss.com/mount-iphone-ipad-ios-7-ubuntu-13-10/"},{default:s(()=>[...e[1]||(e[1]=[n("iPhone在Ubuntu中的掛載問題",-1)])]),_:1}),e[6]||(e[6]=n("。",-1))]),e[23]||(e[23]=h(`<p>我會向你展示如何在Antergos中使用運行iOS 9的iPhone 6S。這會有更多的命令列，但是我假設你用的是ArchLinux，並不懼怕使用終端（也不應該懼怕）。</p><h3 id="在arch-linux中掛載iphone" tabindex="-1">在Arch Linux中掛載iPhone <a class="header-anchor" href="#在arch-linux中掛載iphone" aria-label="Permalink to “在Arch Linux中掛載iPhone”">​</a></h3><p><strong>第一步</strong>：如果已經插入，請拔下你的iPhone。</p><p><strong>第二步</strong>：現在，打開終端輸入下面的命令來安裝必要的包。如果它們已經安裝過了也沒有關係。</p><pre><code>sudo pacman -Sy ifuse usbmuxd libplist libimobiledevice
</code></pre><p><strong>第三步</strong>： 這些庫和程序安裝完成後，重啓系統。</p><pre><code>sudo reboot
</code></pre><p><strong>第四步</strong>：創建一個iPhone的掛載目錄，我建議在家目錄中創建一個iPhone目錄。</p><pre><code>mkdir ~/iPhone
</code></pre><p><strong>第五步</strong>：解鎖你的手機並插入，如果詢問是否信任該計算機，請允許信任。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-mount-Antergos-Linux-2.jpeg" alt=""></p><p><strong>第六步</strong>： 看看這時iPhone是否已經被機器識別了。</p><pre><code>dmesg | grep -i iphone
</code></pre><p>這時就該顯示iPhone和Apple的結果了。就像這樣：</p><pre><code>[ 31.003392] ipheth 2-1:4.2: Apple iPhone USB Ethernet device attached
[ 40.950883] ipheth 2-1:4.2: Apple iPhone USB Ethernet now disconnected
[ 47.471897] ipheth 2-1:4.2: Apple iPhone USB Ethernet device attached
[ 82.967116] ipheth 2-1:4.2: Apple iPhone USB Ethernet now disconnected
[ 106.735932] ipheth 2-1:4.2: Apple iPhone USB Ethernet device attached
</code></pre><p>這意味着這時iPhone已經被Antergos/Arch成功地識別了。</p><p><strong>第七步</strong>: 設置完成後是時候掛載iPhone了，使用下面的命令：</p><pre><code>ifuse ~/iPhone
</code></pre><p>由於我們在家目錄中創建了掛載目錄，你不需要root權限就可以在家目錄中看見。如果命令成功了，你就不會看見任何輸出。</p><p>回到Files看下iPhone是否已經識別。對於我而言，在Antergos中看上去這樣：</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-mount-Antergos-Linux.jpeg" alt=""></p><p>你可以在這個目錄中訪問文件。從這裏複製文件或者複製到裏面。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/10/iPhone-mount-Antergos-Linux-1.jpeg" alt=""></p><p><strong>第八步</strong>： 當你想要卸載的時候，使用這個命令：</p><pre><code>sudo umount ~/iPhone
</code></pre><h3 id="對你有用麼" tabindex="-1">對你有用麼？ <a class="header-anchor" href="#對你有用麼" aria-label="Permalink to “對你有用麼？”">​</a></h3><p>我知道這並不是非常方便和理想，iPhone應該像其他USB設備那樣工作，但是事情並不總是像人們想的那樣。好的是一點小的DIY就能解決這個問題帶來了一點成就感（至少對我而言）。我必須要説的是Antergos應該修復這個問題讓iPhone可以默認掛載。</p><p>這個技巧對你有用麼?如果你有任何問題或者建議，歡迎留下評論。</p><hr>`,29)),o("p",null,[e[8]||(e[8]=n("via: ",-1)),i(t,{href:"http://itsfoss.com/iphone-antergos-linux/"},{default:s(()=>[...e[7]||(e[7]=[n("http://itsfoss.com/iphone-antergos-linux/",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=n("作者：",-1)),i(t,{href:"http://itsfoss.com/author/abhishek/"},{default:s(()=>[...e[9]||(e[9]=[n("Abhishek",-1)])]),_:1}),e[13]||(e[13]=n(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:s(()=>[...e[10]||(e[10]=[n("geekpi",-1)])]),_:1}),e[14]||(e[14]=n(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[11]||(e[11]=[n("wxy",-1)])]),_:1})]),o("p",null,[e[17]||(e[17]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[n("LCTT",-1)])]),_:1}),e[18]||(e[18]=n(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[n("Linux中國",-1)])]),_:1}),e[19]||(e[19]=n(" 榮譽推出",-1))])])}const b=p(u,[["render",a]]);export{T as __pageData,b as default};
